contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value) public {
        require(target != address(0));
        require(value <= c.balanceOf(address(this)));
        // mint funds to target so it can send a transfer
        c.mintToken(target, value);
        uint256 balTargetBefore = c.balanceOf(target);
        uint256 balOwnerBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        // freeze target
        c.freezeAccount(target, true);
        bool reverted;
        try c.transfer(target, value) { reverted = false; }
        catch { reverted = true; }
        // unfreeze target
        c.freezeAccount(target, false);
        c.transfer(target, value);
        assert(
            reverted &&
            c.balanceOf(target) == balTargetBefore &&
            c.balanceOf(address(this)) == balOwnerBefore &&
            c.totalSupply() == supplyBefore
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bool freeze, uint probeAmount) public {
        require(target != address(0));
        require(probeAmount <= c.balanceOf(address(this)));
        bool frozenBefore = c.frozenAccount(target);
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalBefore = c.balanceOf(address(this));
        c.freezeAccount(target, freeze);
        bool frozenAfter = c.frozenAccount(target);
        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalAfter = c.balanceOf(address(this));
        // a transfer to the freshly frozen/unfrozen target reflects the flag's effect
        bool reverted;
        if (freeze) {
            c.transfer(target, probeAmount);
            reverted = false;
        }
        assert(frozenBefore == false && frozenAfter == freeze
            && supplyAfter == supplyBefore && ownerBalAfter == ownerBalBefore);
    }
    receive() external payable {}
}

